package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.time.LocalDate;
import net.officefloor.hq.app.grade.RetiredGradeRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.orm.ObjectOptimisticLockingFailureException;

/** Refuses a grade retired on the sheet, even one the person already has. Saves the person's name, terms (from the form's terms from-date, replacing those recorded for that date and keeping
 *  the others; from the beginning of time when blank), contact and tags, and records their grade from the form's from-date (the sheet's today when blank),
 *  replacing the grade recorded for that date and keeping the others, even when it is the same as the one in force
 *  (a grade with no from-date the same as the one in force on the sheet's today is left unrecorded, so a grade later
 *  recorded from an earlier date still reaches past it); terms with no from-date the same as those already in force are left unrecorded, so terms later recorded from an
 *  earlier date still reach past them. */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, @Val Sheet sheet, PersonRepository repository,
            PersonAliasRepository aliases, TreeNames tree,
            PersonGradeRepository grades, RetiredGradeRepository retired, EntityManager entityManager)
            throws InvalidPersonException, PersonConflictException {
        PersonRules.refuseRetired(person.getSheetId(), request.grade(), retired);
        if (request.version() == null || request.version() != person.getVersion()) {
            throw new PersonConflictException();
        }
        if (repository.existsBySheetIdAndNameIgnoreCaseAndIdNot(person.getSheetId(), request.name(), person.getId())
                || aliases.existsBySheetIdAndAliasIgnoreCase(person.getSheetId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        // A person clashing with the tree may be edited only to a name, with their aliases, that no longer clashes.
        java.util.List<String> names = new java.util.ArrayList<>(java.util.List.of(request.name()));
        aliases.findByPersonIdOrderByIdAsc(person.getId()).forEach(a -> names.add(a.getAlias()));
        if (tree.usedAround(person.getSheetId(), names)) {
            throw new InvalidPersonException("The name or an alias is already in use on a sheet of this sheet's tree.");
        }
        if (request.contactOrNull() != null && repository.existsBySheetIdAndContactAndIdNot(person.getSheetId(),
                request.contactOrNull(), person.getId())) {
            throw new InvalidPersonException("The contact is already in use on this sheet.");
        }
        boolean undated = request.gradeFrom() == null || request.gradeFrom().isEmpty();
        LocalDate from = undated ? sheet.getToday() : LocalDate.parse(request.gradeFrom());
        boolean gradeKept = undated && request.grade().equals(grades.gradesOf(person).on(sheet.getToday()));
        person.setName(request.name());
        if (request.termsFromDate() == null) {
            // Terms left as they are in force on the sheet's today change nothing (their dated history is kept).
            if (!java.util.Objects.equals(request.termsDays(), person.termsOn(sheet.getToday()))) {
                person.setTerms(request.termsDays());
            }
        } else {
            person.setTermsFrom(request.termsFromDate(), request.termsDays());
        }
        person.setContact(request.contactOrNull());
        person.setTags(request.tags());
        try {
            // Every save raises the version, even one that changes only a dated grade.
            entityManager.lock(person, LockModeType.OPTIMISTIC_FORCE_INCREMENT);
            repository.saveAndFlush(person);
        } catch (ObjectOptimisticLockingFailureException | jakarta.persistence.OptimisticLockException e) {
            // saved by someone else between the load and this save
            throw new PersonConflictException();
        }
        // The grade is recorded from the from-date (the sheet's today when none is given), even one the same as the grade in
        // force on that date, so a grade later recorded from an earlier date does not reach past it; a grade with no
        // from-date left as it is in force on the sheet's today changes nothing.
        if (gradeKept) {
            return;
        }
        PersonGrade dated = grades.findByPersonIdAndFromDate(person.getId(), from)
                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), request.grade(), from));
        dated.setGrade(request.grade());
        dated.setMadeOn(sheet.getToday());
        grades.saveAndFlush(dated);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the edited person, once it is saved, with the grade in force on the sheet's today, and their terms in force
 *  on it when the edit changed any of theirs (empty when cleared), and likewise their contact. */
public class AuditPersonEdited {
    public void audit(@Val Person person, @Val Sheet sheet, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        audit.record(PersonRules.editedLine(person, grades.gradesOf(person).on(sheet.getToday()),
                person.termsOn(sheet.getToday()),
                AuditUser.decode(user)));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads the person form from the body, checked by {@link PersonRules#check}: the name trimmed, refusing an empty
 * name or a grade other than A, B or C, a grade or terms from-date that is not a calendar date, and terms that are not a
 * whole number of days; the contact is trimmed and lower-cased.
 */
public class ValidatePerson {
    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        if (request == null) {
            throw new InvalidPersonException("A name is required.");
        }
        body.set(PersonRules.check(request.name(), request.grade(), request.version(), request.gradeFrom(),
                request.terms(), request.contact(), request.tags()).withTermsFrom(PersonRules.checkTermsFrom(request.termsFrom())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Long id;
        try {
            id = Long.valueOf(personId.trim());
        } catch (NumberFormatException e) {
            throw new PersonNotFoundException(personId);
        }
        personOut.set(repository.findByIdAndSheetId(id, sheetId.trim())
                .orElseThrow(() -> new PersonNotFoundException(personId)));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person's grades over time: the first grade they were given applies from the beginning of time, each dated
 *  grade from its from-date on.
 *  @param first the grade they were first given.
 *  @param dated their dated grades, by from-date. */
public record PersonGrades(String first, List<PersonGrade> dated) {

    /** Their grades as they stood at the end of a date: only the dated grades recorded while the sheet's today was
     *  on or before it. */
    public PersonGrades asOf(LocalDate date) {
        return new PersonGrades(first, dated.stream().filter(g -> g.madeBy(date)).toList());
    }

    /** The grade in force on a date: the dated grade whose from-date is the latest on or before it, else the first. */
    public String on(LocalDate date) {
        String grade = first;
        for (PersonGrade g : dated) {
            if (date != null && !g.getFromDate().isAfter(date)) {
                grade = g.getGrade();
            }
        }
        return grade;
    }
}
package net.officefloor.hq.app.person;

/** The person form as submitted: a name and a grade, their own terms in days (blank: none), their contact (trimmed and lower-cased; blank: none), their tags (comma separated; as stored, null for none), and for an edit the version of the person it loaded and the
 *  date the grade applies from (blank: the sheet's today), and the date the terms apply from (blank: the beginning of time). */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms,
        String contact, String tags, String termsFrom) {

    public PersonRequest(String name, String grade, Long version, String gradeFrom, String terms,
            String contact, String tags) {
        this(name, grade, version, gradeFrom, terms, contact, tags, "");
    }

    /** The date the terms apply from; null when blank (the beginning of time). */
    public java.time.LocalDate termsFromDate() {
        return termsFrom == null || termsFrom.isEmpty() ? null : java.time.LocalDate.parse(termsFrom);
    }

    /** This form with the terms from-date given. */
    public PersonRequest withTermsFrom(String termsFrom) {
        return new PersonRequest(name, grade, version, gradeFrom, terms, contact, tags, termsFrom);
    }

    /** This form with the grade given. */
    public PersonRequest withGrade(String grade) {
        return new PersonRequest(name, grade, version, gradeFrom, terms, contact, tags, termsFrom);
    }

    /** The terms as a number of days; null when blank. */
    public Integer termsDays() {
        return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms);
    }

    /** The contact; null when blank. */
    public String contactOrNull() {
        return contact == null || contact.isEmpty() ? null : contact;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.history.AsOf;
import net.officefloor.hq.app.sheet.InvalidTodayException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's people; as of a date (asOf), as they stood at the end of it. */
public class RespondWithPeople {
    public void respond(@Val Sheet sheet, @RequestParam(name = "asOf", required = false) String asOfParam, AsOf asOf, TreeNames tree,
            ObjectResponse<List<PersonResponse>> response) throws InvalidTodayException {
        LocalDate date = AsOf.dateOf(asOfParam);
        Sheet view = asOf.sheet(sheet, date);
        Map<Long, List<Statement>> byPerson = asOf.statements(sheet.getId(), date).stream()
                .collect(Collectors.groupingBy(Statement::getPersonId));
        Map<Long, List<Patron>> patronsOf = asOf.patrons(sheet.getId(), date).stream()
                .collect(Collectors.groupingBy(Patron::getPersonId));
        Map<Long, List<PersonAlias>> aliasesOf = asOf.aliases(sheet.getId(), date).stream()
                .collect(Collectors.groupingBy(PersonAlias::getPersonId));
        Map<Long, List<PersonGrade>> gradesOf = asOf.grades(sheet.getId(), date);
        java.util.Set<String> usedAround = tree.usedAround(sheet.getId());
        response.send(asOf.people(sheet.getId(), date).stream()
                .map(p -> PersonResponse.from(p, byPerson.getOrDefault(p.getId(), List.of()),
                        patronsOf.getOrDefault(p.getId(), List.of()),
                        aliasesOf.getOrDefault(p.getId(), List.of()),
                        new PersonGrades(p.getGrade(), gradesOf.getOrDefault(p.getId(), List.of())), view.getToday(), usedAround))
                .toList());
    }
}

